INSERT INTO `career` (`id`, `heading`, `location`, `department`, `description`, `time`, `delete_status`) VALUES
(1, 'UX Designer', 'Nashik Maharashtra', 'Engineering', '<p>We are seeking a Senior Software Engineer to join our dynamic team in Bangalore. The ideal candidate will have extensive experience in full-stack development, with expertise in Java, JavaScript, and React. This role offers the opportunity to work on innovative projects and contribute to the growth of our company.</p><p>Role Introduction</p><p>We are seeking a Senior Software Engineer to join our dynamic team in Bangalore. The ideal candidate will have extensive experience in full-stack development, with expertise in Java, JavaScript, and React. This role offers the opportunity to work on innovative projects and contribute to the growth of our company.</p><p>Job Responsibility and Duties</p><ul><li>Design, develop, and maintain high-quality software solutions using Java, JavaScript, and React.</li><li>Collaborate with cross-functional teams to understand project requirements and translate them into technical specifications.</li><li>Conduct code reviews and ensure adherence to coding standards and best practices.</li><li>Architect scalable and efficient solutions that meet the needs of the business and align with industry standards.</li><li>Participate in agile ceremonies such as sprint planning, daily stand-ups, and retrospectives.</li></ul>', 2, 0),
(2, 'Web Designer', 'Mumbai Maharashtra', 'Engineering', '<p>We are seeking a Senior Software Engineer to join our dynamic team in Bangalore. The ideal candidate will have extensive experience in full-stack development, with expertise in Java, JavaScript, and React. This role offers the opportunity to work on innovative projects and contribute to the growth of our company.</p><p>Role Introduction</p><p>We are seeking a Senior Software Engineer to join our dynamic team in Bangalore. The ideal candidate will have extensive experience in full-stack development, with expertise in Java, JavaScript, and React. This role offers the opportunity to work on innovative projects and contribute to the growth of our company.</p><p>Job Responsibility and Duties</p><ul><li>Design, develop, and maintain high-quality software solutions using Java, JavaScript, and React.</li><li>Collaborate with cross-functional teams to understand project requirements and translate them into technical specifications.</li><li>Conduct code reviews and ensure adherence to coding standards and best practices.</li><li>Architect scalable and efficient solutions that meet the needs of the business and align with industry standards.</li><li>Participate in agile ceremonies such as sprint planning, daily stand-ups, and retrospectives.</li></ul>', 1, 0),
(3, 'Digital Marketer', 'Nagpur Maharashtra', 'Engineering', '<p>We are seeking a Senior Software Engineer to join our dynamic team in Bangalore. The ideal candidate will have extensive experience in full-stack development, with expertise in Java, JavaScript, and React. This role offers the opportunity to work on innovative projects and contribute to the growth of our company.</p><p>Role Introduction</p><p>We are seeking a Senior Software Engineer to join our dynamic team in Bangalore. The ideal candidate will have extensive experience in full-stack development, with expertise in Java, JavaScript, and React. This role offers the opportunity to work on innovative projects and contribute to the growth of our company.</p><p>Job Responsibility and Duties</p><ul><li>Design, develop, and maintain high-quality software solutions using Java, JavaScript, and React.</li><li>Collaborate with cross-functional teams to understand project requirements and translate them into technical specifications.</li><li>Conduct code reviews and ensure adherence to coding standards and best practices.</li><li>Architect scalable and efficient solutions that meet the needs of the business and align with industry standards.</li><li>Participate in agile ceremonies such as sprint planning, daily stand-ups, and retrospectives.</li></ul>', 1, 0);
