INSERT INTO `communications` (`id`, `communication`, `created_at`, `status`) VALUES
(1, '<p>Communication&nbsp;</p>', '2025-05-19 12:41:39', 0),
(2, '<ol><li>God is raising ministers that bear His heart, ministers that are dead to self but alive fully to GOD.</li><li>Expansion&nbsp;</li></ol>', '2025-05-20 05:51:11', 0),
(3, '<ol><li>Emphasis on the mandate, transformation of the mindset to men.</li><li>Mindset transformation is progressive.&nbsp;</li><li>Habakkuk 2.1, 3</li><li>Empowerment, through the grace of God.</li></ol>', '2025-08-13 17:23:59', 0),
(4, '<ol><li>The unity of believers among the ministries that are rising in Kenya that began from Kimathi, they are the beacon of the Unity of Believers, they carry the perfect picture of the Church.</li><li>Intentionality in the pray for the above, as it will bring the clarity of the Gospel from the same.</li><li>Glory during the December conference,</li><li>Presidential convoy.</li><li>God is ready to surprise and amaze.</li><li>Strategic partner for the conferences.</li><li>Raising people among who have an excellent spirit.</li></ol>', '2025-08-14 17:23:34', 0),
(5, '<p>Communications&nbsp;</p><ol><li>Psalms 34:8-10 - Godly provisions, no wants</li><li>God is establishing us early</li><li>The ease of manifestation</li><li>He that began a good work in us he is sure to accomplish - Isaiah 55:10</li><li>Empowering men - and building people to help in accomplishing his success.</li><li>Grace - Empowering to fulfill his purpose,</li><li>Favour to be accepted of men and the world</li><li>God is giving us an identity - a name,</li><li>God is uniquely using everyone in the Jesus enthroned network</li><li>The differences shall be the point of our unity, the difference united-</li><li>Influencing with ease to the young generation.</li></ol>', '2025-08-15 12:37:20', 0),
(6, '<ol><li>God has provided men in every place that we will have to be &nbsp;God has availed men to push the work and the vision of God ahead.</li><li>Men will be empowered to accomplish the vision of God upon Jesus Enthroned Network</li><li>1 Samuel 10:1-7, Psalms 92:10&nbsp;</li></ol>', '2025-08-15 17:14:26', 0),
(7, '<ol><li>God is establishing us early - Ecclessiates 9:11&nbsp;</li><li>Be lead of him, manifestation of the Gifts of the Holy Spirit will made possible,</li><li>God is establishing us building us individually</li></ol>', '2025-08-16 16:32:37', 0),
(8, '<ol><li>God is going to define the purposes of the God and the very lives</li><li>Zechariah 13:9 Refiners of God,&nbsp;</li><li>Tremendous Growth in the lives of men.</li><li>Confirming the vision of God in the hearts of men.</li></ol>', '2025-08-18 17:01:04', 0),
(9, '<blockquote><ol><li>Grace to accelerate, things that have taken other to establish will take us a short time</li><li>There is grace for the laborers.&nbsp;</li><li>God is establishing in the Media and Tech – It is for us to position ourselves in skill, excellence&nbsp;</li></ol></blockquote>', '2025-08-28 16:58:56', 0),
(10, '<blockquote><ol><li>Victory - We are walking in victory</li><li>There is a multiplication in our lives and in the organizations</li><li>&nbsp;</li></ol></blockquote>', '2025-08-29 16:55:58', 0),
(11, '<ul><li>Divine Directions</li><li>Divine growth, divine elevations, and divine building</li></ul>', '2026-01-16 18:11:25', 0),
(12, '<ol><li>Manifestation of wisdom</li><li>We depend on him</li></ol>', '2026-01-17 18:01:54', 0),
(13, '<ol><li>Deutronomy 28:8<br>A command on the blessing on hour houses and barns.&nbsp;<br>The work of our hands is blessed. Everything that concerns us is perfected.&nbsp;<br>Opportunities are opening up.</li><li>Depend on God in the journey that we are taking.&nbsp;<br>Things that have taken men years to establsih shal take us for a short time</li><li>Trust on God and depend on the working of God<br>&nbsp;</li><li>God is giving the wisdom to make wealth.</li></ol>', '2026-01-18 18:22:45', 0),
(14, '<ol><li>Go &nbsp;is bringing more laborers in the ministry</li><li>Excellency in ministry</li><li>What we believe shall be practical</li><li>Progress - We are making progress</li><li>Wisdom to strategize to have a long lasting structure.</li></ol>', '2026-01-19 17:53:18', 0),
(15, '<ol><li>Abilitised to prosper</li><li>The need to mentor the Form 4 graduation</li><li>God is ministering clarity in all activities.</li></ol>', '2026-01-21 18:04:00', 0),
(16, '<ol><li>Be courageous&nbsp;</li><li>Whatever our hands finds to do is prospers</li><li>Acquaint yourself with him and good comes Job 22.21</li><li>Trust in God and everything has been aligned&nbsp;</li><li>Form 4, God is&nbsp;</li><li>Right people</li><li>Good clients</li></ol>', '2026-01-22 18:38:30', 0),
(17, '<ol><li>Forms to be mentored</li><li>&nbsp;</li></ol>', '2026-01-23 18:05:22', 0),
(18, '<p>Psalms 8</p><p>God is with usabs never forsake us</p><p>God influence is making to influence&nbsp;</p>', '2026-01-26 18:00:36', 0),
(19, '<ol><li>Philippians 4:6 - Make request to God</li><li>Influence, by the influence comes business</li></ol>', '2026-01-28 18:12:07', 0),
(20, '<ol><li>John 14.1 Faith in God and trusting in God.</li><li>God is inviting us &nbsp;fellowship&nbsp;</li></ol>', '2026-02-01 18:07:33', 0);
